import pandas as pd
from collections import Counter
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded character-prefix optimizer using global and repeated pair prefixes."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Convert a scalar to evaluator text, representing scalar missing values as empty text."""
        try:
            missing = pd.isna(value)
            if not hasattr(missing, "__len__") and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slice comparisons."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute exact reusable character edges from sorted adjacent serialized rows."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested merge groups contiguous while preserving their proposed order."""
        if not col_merge:
            return list(order)

        positions = {column: index for index, column in enumerate(order)}
        owners = {}
        claimed = set()

        for requested in col_merge:
            group = [
                column for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=positions.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Convert integer column order to a complete valid order after merge constraints."""
        proposed = [columns[index] for index in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: index for index, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every row according to its row-specific integer column ordering."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Build frequency-ranked and partial-prefix-ranked global column orders."""
        rows = len(text)
        width = len(columns)
        whole_mass = []
        prefix_mass = []

        for column in range(width):
            values = Counter(text[row][column] for row in range(rows))
            mass = sum(
                len(value) * count * (count - 1)
                for value, count in values.items()
            )
            whole_mass.append((mass, len(values)))

            prefixes = Counter()
            for value, count in values.items():
                for length in range(1, min(8, len(value)) + 1):
                    prefixes[value[:length]] += count

            partial = sum(
                len(prefix) * count * (count - 1)
                for prefix, count in prefixes.items()
            )
            prefix_mass.append((partial, len(prefixes)))

        frequency_ranked = sorted(
            range(width),
            key=lambda column: (
                -whole_mass[column][0],
                whole_mass[column][1],
                column,
            ),
        )

        prefix_ranked = sorted(
            range(width),
            key=lambda column: (
                -prefix_mass[column][0],
                prefix_mass[column][1],
                -whole_mass[column][0],
                column,
            ),
        )

        return [
            self._normalize(columns, frequency_ranked, col_merge),
            self._normalize(columns, prefix_ranked, col_merge),
        ], frequency_ranked

    def _pair_prefix_candidate(self, text, columns, col_merge, base_order):
        """Place the most globally repeated ordered field pair first for each row."""
        rows = len(text)
        width = len(columns)
        fallback = self._normalize(columns, base_order, col_merge)
        result = [fallback[:] for _ in range(rows)]

        if rows < 2 or width < 2:
            return result

        active = list(base_order[:min(width, 12)])
        pairs = [
            (left, right)
            for left in active
            for right in active
            if left != right
        ]

        # Pair counting is intentionally bounded as specified by the strategy.
        if rows * len(pairs) > 250000:
            return result

        pair_counts = []
        for left, right in pairs:
            counts = Counter(
                text[row][left] + text[row][right]
                for row in range(rows)
            )
            pair_counts.append(counts)

        for row in range(rows):
            best_pair = None
            best_score = -1
            best_length = -1

            for pair_index, (left, right) in enumerate(pairs):
                value = text[row][left] + text[row][right]
                count = pair_counts[pair_index][value]
                score = len(value) * (count - 1)

                if (
                    score > best_score
                    or (
                        score == best_score
                        and len(value) > best_length
                    )
                ):
                    best_score = score
                    best_length = len(value)
                    best_pair = (left, right)

            if best_pair is None or best_score <= 0:
                continue

            left, right = best_pair
            chosen = [left, right]
            tail = [
                column for column in base_order
                if column != left and column != right
            ]
            result[row] = self._normalize(
                columns,
                chosen + tail,
                col_merge,
            )

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global layouts and one bounded repeated-pair layout, returning the best."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(width)]
            for row in range(rows)
        ]

        global_orders, base_order = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []

        for order in global_orders:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append((
                self._reuse(serialized),
                orders,
                serialized,
            ))

        pair_orders = self._pair_prefix_candidate(
            text,
            columns,
            col_merge,
            base_order,
        )
        pair_serialized = self._serialize(text, pair_orders)
        candidates.append((
            self._reuse(pair_serialized),
            pair_orders,
            pair_serialized,
        ))

        _, best_orders, best_serialized = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(
            range(rows),
            key=lambda row: best_serialized[row],
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]

        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings
